-- Flight App database initialization
-- Generated from the verified flight-app-backup.sql
-- Intended for a fresh PostgreSQL database.

-- Sequences
CREATE SEQUENCE public.flights_id_seq;
CREATE SEQUENCE public.states_id_seq;
CREATE SEQUENCE public.tickets_id_seq;
CREATE SEQUENCE public.users_id_seq;

-- Tables
CREATE TABLE public.flights (
    id integer NOT NULL,
    departure_state varchar(255) NOT NULL,
    arrival_state varchar(255) NOT NULL,
    departure_time timestamp without time zone NOT NULL,
    arrival_time timestamp without time zone NOT NULL,
    price numeric(10,2) NOT NULL
);

CREATE TABLE public.states (
    id integer NOT NULL,
    state_code varchar(2) NOT NULL,
    state_name varchar(50) NOT NULL
);

CREATE TABLE public.tickets (
    id integer NOT NULL,
    ticket_number varchar(50) NOT NULL,
    departure_state varchar(50) NOT NULL,
    arrival_state varchar(50) NOT NULL,
    departure_time timestamp without time zone NOT NULL,
    arrival_time timestamp without time zone NOT NULL,
    ticket_price numeric(10,2) NOT NULL,
    status varchar(20) DEFAULT 'CONFIRMED'::varchar NOT NULL,
    user_id integer NOT NULL
);

CREATE TABLE public.users (
    id integer NOT NULL,
    name varchar(50) NOT NULL,
    password varchar(255) NOT NULL,
    email varchar(255) NOT NULL
);

-- ID defaults
ALTER TABLE ONLY public.flights
    ALTER COLUMN id SET DEFAULT nextval('public.flights_id_seq'::regclass);

ALTER TABLE ONLY public.states
    ALTER COLUMN id SET DEFAULT nextval('public.states_id_seq'::regclass);

ALTER TABLE ONLY public.tickets
    ALTER COLUMN id SET DEFAULT nextval('public.tickets_id_seq'::regclass);

ALTER TABLE ONLY public.users
    ALTER COLUMN id SET DEFAULT nextval('public.users_id_seq'::regclass);

-- Sequence ownership
ALTER SEQUENCE public.flights_id_seq OWNED BY public.flights.id;
ALTER SEQUENCE public.states_id_seq OWNED BY public.states.id;
ALTER SEQUENCE public.tickets_id_seq OWNED BY public.tickets.id;
ALTER SEQUENCE public.users_id_seq OWNED BY public.users.id;


-- Restore sequence positions
SELECT pg_catalog.setval('public.flights_id_seq', 2450, true);
SELECT pg_catalog.setval('public.states_id_seq', 50, true);
SELECT pg_catalog.setval('public.tickets_id_seq', 16, true);
SELECT pg_catalog.setval('public.users_id_seq', 5, true);

-- Constraints
ALTER TABLE ONLY public.flights
    ADD CONSTRAINT flights_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.states
    ADD CONSTRAINT states_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.tickets
    ADD CONSTRAINT tickets_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.tickets
    ADD CONSTRAINT unique_ticket_number UNIQUE (ticket_number);

ALTER TABLE ONLY public.users
    ADD CONSTRAINT users_email_unique UNIQUE (email);

ALTER TABLE ONLY public.users
    ADD CONSTRAINT users_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.tickets
    ADD CONSTRAINT tickets_user_id_fkey
    FOREIGN KEY (user_id)
    REFERENCES public.users(id)
    ON DELETE CASCADE;
